// UpdateRiskPrivacyDetails is the resolver for the updateRiskPrivacyDetails field.
func (r *mutationResolver) UpdateRiskPrivacyDetails(ctx context.Context, input types.UpdateRiskPrivacyDetailsInput) (*types.UpdateRiskPrivacyDetailsPayload, error) {
	scope, err := r.authorize(ctx, input.RiskID, probo.ActionRiskUpdate)
	if err != nil {
		return nil, err
	}

	// Linking needs to see the processing activities.
	if input.ProcessingActivityIds.IsSet() {
		if _, err := r.authorize(ctx, input.RiskID, probo.ActionProcessingActivityList); err != nil {
			return nil, err
		}
	}

	req := probo.UpdateRiskPrivacyDetailsRequest{
		RiskID:                input.RiskID,
		LifecycleStages:       unwrapOmittableList(input.LifecycleStages),
		ProcessingActivityIDs: unwrapOmittableList(input.ProcessingActivityIds),
	}

	if err := r.probo.RiskPrivacy.UpdateDetails(ctx, scope, &req); err != nil {
		if errs, ok := errors.AsType[validator.ValidationErrors](err); ok {
			return nil, gqlutils.InvalidValidationErrors(ctx, errs)
		}

		if errors.Is(err, coredata.ErrResourceNotFound) {
			return nil, gqlutils.NotFoundf(ctx, "risk or processing activity not found")
		}

		r.logger.ErrorCtx(ctx, "cannot update risk privacy details", log.Error(err))
		return nil, gqlutils.Internal(ctx)
	}

	risk, err := r.probo.Risks.Get(ctx, scope, input.RiskID)
	if err != nil {
		r.logger.ErrorCtx(ctx, "cannot get risk", log.Error(err))
		return nil, gqlutils.Internal(ctx)
	}

	return &types.UpdateRiskPrivacyDetailsPayload{
		Risk: types.NewRisk(risk),
	}, nil
}

// ExportRiskPrivacySheet is the resolver for the exportRiskPrivacySheet field.
func (r *mutationResolver) ExportRiskPrivacySheet(ctx context.Context, input types.ExportRiskPrivacySheetInput) (*types.ExportRiskPrivacySheetPayload, error) {
	// The sheet lists register entries, internal controls and risk owners
	// besides the risks.
	for _, action := range []string{
		probo.ActionProcessingActivityList,
		probo.ActionInternalControlList,
		iam.ActionMembershipProfileList,
	} {
		if _, err := r.authorize(ctx, input.OrganizationID, action); err != nil {
			return nil, err
		}
	}

	scope, err := r.authorize(ctx, input.OrganizationID, probo.ActionRiskList)
	if err != nil {
		return nil, err
	}

	workbook, err := r.probo.RiskPrivacy.Export(ctx, scope, input.OrganizationID)
	if err != nil {
		r.logger.ErrorCtx(ctx, "cannot export risk analysis", log.Error(err))
		return nil, gqlutils.Internal(ctx)
	}

	return &types.ExportRiskPrivacySheetPayload{
		Data: fmt.Sprintf("data:%s;base64,%s", xlsxexport.ContentType, base64.StdEncoding.EncodeToString(workbook)),
	}, nil
}
